sys_script_fix.script:
(function() {

    var total = 0;
    var ownerUpdated = 0;
    var technicianUpdated = 0;
    var ownerUnmatched = 0;
    var technicianUnmatched = 0;

    var gr = new GlideRecord('x_1947064_autoca_0_appointment');
    gr.query();

    while (gr.next()) {

        total++;

        // -----------------------------
        // OWNER
        // -----------------------------
        var ownerName = gr.getValue('owner');

        if (ownerName) {

            var ownerUser = new GlideRecord('sys_user');
            ownerUser.addQuery('name', ownerName);
            ownerUser.setLimit(1);
            ownerUser.query();

            if (ownerUser.next()) {
                gr.setValue('owner', ownerUser.getUniqueValue());
                ownerUpdated++;
            } else {
                ownerUnmatched++;
                gs.info('OWNER NOT FOUND: ' + ownerName);
            }
        }

        // -----------------------------
        // ASSIGNED TECHNICIAN
        // -----------------------------
        var technicianName = gr.getValue('assigned_technician');

        if (technicianName) {

            var technicianUser = new GlideRecord('sys_user');
            technicianUser.addQuery('name', technicianName);
            technicianUser.setLimit(1);
            technicianUser.query();

            if (technicianUser.next()) {
                gr.setValue(
                    'assigned_technician',
                    technicianUser.getUniqueValue()
                );
                technicianUpdated++;
            } else {
                technicianUnmatched++;
                gs.info(
                    'TECHNICIAN NOT FOUND: ' +
                    technicianName
                );
            }
        }

        gr.update();
    }

    gs.info('======================================');
    gs.info('APPOINTMENT USER REFERENCE PREPARATION');
    gs.info('======================================');
    gs.info('TOTAL APPOINTMENTS = ' + total);
    gs.info('OWNER UPDATED = ' + ownerUpdated);
    gs.info('OWNER UNMATCHED = ' + ownerUnmatched);
    gs.info('TECHNICIAN UPDATED = ' + technicianUpdated);
    gs.info('TECHNICIAN UNMATCHED = ' + technicianUnmatched);
    gs.info('======================================');

})();
